// MetricsBuilder accumulates one scrape's worth of datapoints and hands them
// over as a pmetric.Metrics.
//
// It is not safe for concurrent use: a scraper owns one and drives it from a
// single scrape.
type MetricsBuilder struct {
	startTime                                  pcommon.Timestamp
	scopeName                                  string
	scopeVersion                               string
	metricDBClientConnectionCount              metricDBClientConnectionCount
	metricDBClientConnectionIdleMin            metricDBClientConnectionIdleMin
	metricDBClientConnectionMax                metricDBClientConnectionMax
	metricDBClientConnectionPendingRequests    metricDBClientConnectionPendingRequests
	metricPgbouncerClientConnectionCount       metricPgbouncerClientConnectionCount
	metricPgbouncerClientConnectionDetailCount metricPgbouncerClientConnectionDetailCount
	metricPgbouncerClientConnectionMax         metricPgbouncerClientConnectionMax
	metricPgbouncerClientCount                 metricPgbouncerClientCount
	metricPgbouncerClientWaitMax               metricPgbouncerClientWaitMax
	metricPgbouncerClientWaitTime              metricPgbouncerClientWaitTime
	metricPgbouncerDatabaseConnectionCount     metricPgbouncerDatabaseConnectionCount
	metricPgbouncerDatabaseConnectionMax       metricPgbouncerDatabaseConnectionMax
	metricPgbouncerDatabaseCount               metricPgbouncerDatabaseCount
	metricPgbouncerDatabaseDisabled            metricPgbouncerDatabaseDisabled
	metricPgbouncerDatabasePaused              metricPgbouncerDatabasePaused
	metricPgbouncerDatabaseReservePoolSize     metricPgbouncerDatabaseReservePoolSize
	metricPgbouncerDNSCacheCount               metricPgbouncerDNSCacheCount
	metricPgbouncerDNSQueryCount               metricPgbouncerDNSQueryCount
	metricPgbouncerNetworkIO                   metricPgbouncerNetworkIO
	metricPgbouncerPoolCount                   metricPgbouncerPoolCount
	metricPgbouncerPreparedStatementCount      metricPgbouncerPreparedStatementCount
	metricPgbouncerQueryCount                  metricPgbouncerQueryCount
	metricPgbouncerQueryTime                   metricPgbouncerQueryTime
	metricPgbouncerServerAssignmentCount       metricPgbouncerServerAssignmentCount
	metricPgbouncerServerCount                 metricPgbouncerServerCount
	metricPgbouncerTransactionCount            metricPgbouncerTransactionCount
	metricPgbouncerTransactionTime             metricPgbouncerTransactionTime
	metricPgbouncerUserConnectionMax           metricPgbouncerUserConnectionMax
	metricPgbouncerUserCount                   metricPgbouncerUserCount
}

// NewMetricsBuilder returns a builder gated by config. startTime is the process
// start, reported on every cumulative datapoint so a consumer can tell a reset
// from a genuine drop.
func NewMetricsBuilder(config MetricsConfig, startTime pcommon.Timestamp, scopeName, scopeVersion string) *MetricsBuilder {
	mb := &MetricsBuilder{
		startTime:                                  startTime,
		scopeName:                                  scopeName,
		scopeVersion:                               scopeVersion,
		metricDBClientConnectionCount:              metricDBClientConnectionCount{data: pmetric.NewMetric(), config: config.DBClientConnectionCount},
		metricDBClientConnectionIdleMin:            metricDBClientConnectionIdleMin{data: pmetric.NewMetric(), config: config.DBClientConnectionIdleMin},
		metricDBClientConnectionMax:                metricDBClientConnectionMax{data: pmetric.NewMetric(), config: config.DBClientConnectionMax},
		metricDBClientConnectionPendingRequests:    metricDBClientConnectionPendingRequests{data: pmetric.NewMetric(), config: config.DBClientConnectionPendingRequests},
		metricPgbouncerClientConnectionCount:       metricPgbouncerClientConnectionCount{data: pmetric.NewMetric(), config: config.PgbouncerClientConnectionCount},
		metricPgbouncerClientConnectionDetailCount: metricPgbouncerClientConnectionDetailCount{data: pmetric.NewMetric(), config: config.PgbouncerClientConnectionDetailCount},
		metricPgbouncerClientConnectionMax:         metricPgbouncerClientConnectionMax{data: pmetric.NewMetric(), config: config.PgbouncerClientConnectionMax},
		metricPgbouncerClientCount:                 metricPgbouncerClientCount{data: pmetric.NewMetric(), config: config.PgbouncerClientCount},
		metricPgbouncerClientWaitMax:               metricPgbouncerClientWaitMax{data: pmetric.NewMetric(), config: config.PgbouncerClientWaitMax},
		metricPgbouncerClientWaitTime:              metricPgbouncerClientWaitTime{data: pmetric.NewMetric(), config: config.PgbouncerClientWaitTime},
		metricPgbouncerDatabaseConnectionCount:     metricPgbouncerDatabaseConnectionCount{data: pmetric.NewMetric(), config: config.PgbouncerDatabaseConnectionCount},
		metricPgbouncerDatabaseConnectionMax:       metricPgbouncerDatabaseConnectionMax{data: pmetric.NewMetric(), config: config.PgbouncerDatabaseConnectionMax},
		metricPgbouncerDatabaseCount:               metricPgbouncerDatabaseCount{data: pmetric.NewMetric(), config: config.PgbouncerDatabaseCount},
		metricPgbouncerDatabaseDisabled:            metricPgbouncerDatabaseDisabled{data: pmetric.NewMetric(), config: config.PgbouncerDatabaseDisabled},
		metricPgbouncerDatabasePaused:              metricPgbouncerDatabasePaused{data: pmetric.NewMetric(), config: config.PgbouncerDatabasePaused},
		metricPgbouncerDatabaseReservePoolSize:     metricPgbouncerDatabaseReservePoolSize{data: pmetric.NewMetric(), config: config.PgbouncerDatabaseReservePoolSize},
		metricPgbouncerDNSCacheCount:               metricPgbouncerDNSCacheCount{data: pmetric.NewMetric(), config: config.PgbouncerDNSCacheCount},
		metricPgbouncerDNSQueryCount:               metricPgbouncerDNSQueryCount{data: pmetric.NewMetric(), config: config.PgbouncerDNSQueryCount},
		metricPgbouncerNetworkIO:                   metricPgbouncerNetworkIO{data: pmetric.NewMetric(), config: config.PgbouncerNetworkIO},
		metricPgbouncerPoolCount:                   metricPgbouncerPoolCount{data: pmetric.NewMetric(), config: config.PgbouncerPoolCount},
		metricPgbouncerPreparedStatementCount:      metricPgbouncerPreparedStatementCount{data: pmetric.NewMetric(), config: config.PgbouncerPreparedStatementCount},
		metricPgbouncerQueryCount:                  metricPgbouncerQueryCount{data: pmetric.NewMetric(), config: config.PgbouncerQueryCount},
		metricPgbouncerQueryTime:                   metricPgbouncerQueryTime{data: pmetric.NewMetric(), config: config.PgbouncerQueryTime},
		metricPgbouncerServerAssignmentCount:       metricPgbouncerServerAssignmentCount{data: pmetric.NewMetric(), config: config.PgbouncerServerAssignmentCount},
		metricPgbouncerServerCount:                 metricPgbouncerServerCount{data: pmetric.NewMetric(), config: config.PgbouncerServerCount},
		metricPgbouncerTransactionCount:            metricPgbouncerTransactionCount{data: pmetric.NewMetric(), config: config.PgbouncerTransactionCount},
		metricPgbouncerTransactionTime:             metricPgbouncerTransactionTime{data: pmetric.NewMetric(), config: config.PgbouncerTransactionTime},
		metricPgbouncerUserConnectionMax:           metricPgbouncerUserConnectionMax{data: pmetric.NewMetric(), config: config.PgbouncerUserConnectionMax},
		metricPgbouncerUserCount:                   metricPgbouncerUserCount{data: pmetric.NewMetric(), config: config.PgbouncerUserCount},
	}
	mb.metricDBClientConnectionCount.init()
	mb.metricDBClientConnectionIdleMin.init()
	mb.metricDBClientConnectionMax.init()
	mb.metricDBClientConnectionPendingRequests.init()
	mb.metricPgbouncerClientConnectionCount.init()
	mb.metricPgbouncerClientConnectionDetailCount.init()
	mb.metricPgbouncerClientConnectionMax.init()
	mb.metricPgbouncerClientCount.init()
	mb.metricPgbouncerClientWaitMax.init()
	mb.metricPgbouncerClientWaitTime.init()
	mb.metricPgbouncerDatabaseConnectionCount.init()
	mb.metricPgbouncerDatabaseConnectionMax.init()
	mb.metricPgbouncerDatabaseCount.init()
	mb.metricPgbouncerDatabaseDisabled.init()
	mb.metricPgbouncerDatabasePaused.init()
	mb.metricPgbouncerDatabaseReservePoolSize.init()
	mb.metricPgbouncerDNSCacheCount.init()
	mb.metricPgbouncerDNSQueryCount.init()
	mb.metricPgbouncerNetworkIO.init()
	mb.metricPgbouncerPoolCount.init()
	mb.metricPgbouncerPreparedStatementCount.init()
	mb.metricPgbouncerQueryCount.init()
	mb.metricPgbouncerQueryTime.init()
	mb.metricPgbouncerServerAssignmentCount.init()
	mb.metricPgbouncerServerCount.init()
	mb.metricPgbouncerTransactionCount.init()
	mb.metricPgbouncerTransactionTime.init()
	mb.metricPgbouncerUserConnectionMax.init()
	mb.metricPgbouncerUserCount.init()
	return mb
}

// RecordDBClientConnectionCount records one datapoint of db.client.connection.count.
//
// Connections PgBouncer holds to PostgreSQL, by state.
//
// One datapoint per (pool, state). PgBouncer reports seven server states and `db.client.connection.state` defines two, so five carry local values: `used_pending_check`, `tested`, `login`, `active_cancel`, `being_canceled`.
// `sv_used` is deliberately *not* reported as `used`. PgBouncer's `sv_used` means idle for longer than `server_check_delay` and needing a check query before reuse -- an idle connection. Upstream `used` means in use, which is `sv_active`. Aliasing the two by name would double-count against `sv_active` and invert the metric people alert on.
//
// Instrument: updowncounter. Unit: {connection}. Stability: development.
func (mb *MetricsBuilder) RecordDBClientConnectionCount(ts pcommon.Timestamp, value int64, attrs DBClientConnectionCountAttributes) {
	mb.metricDBClientConnectionCount.record(mb.startTime, ts, value, attrs)
}

// RecordDBClientConnectionIdleMin records one datapoint of db.client.connection.idle.min.
//
// Server connections PgBouncer keeps open when idle.
//
// PgBouncer's `min_pool_size`, from `SHOW DATABASES`. The upstream exporter does not emit it; it is surface we add, so it has no Prometheus source and is excluded from the compat scope.
//
// Instrument: updowncounter. Unit: {connection}. Stability: development.
func (mb *MetricsBuilder) RecordDBClientConnectionIdleMin(ts pcommon.Timestamp, value int64, attrs DBClientConnectionIdleMinAttributes) {
	mb.metricDBClientConnectionIdleMin.record(mb.startTime, ts, value, attrs)
}

// RecordDBClientConnectionMax records one datapoint of db.client.connection.max.
//
// Maximum server connections PgBouncer will open for a pool.
//
// PgBouncer's `pool_size`, from `SHOW DATABASES`.
//
// Instrument: updowncounter. Unit: {connection}. Stability: development.
func (mb *MetricsBuilder) RecordDBClientConnectionMax(ts pcommon.Timestamp, value int64, attrs DBClientConnectionMaxAttributes) {
	mb.metricDBClientConnectionMax.record(mb.startTime, ts, value, attrs)
}

// RecordDBClientConnectionPendingRequests records one datapoint of db.client.connection.pending_requests.
//
// Clients queued waiting for a server connection.
//
// PgBouncer's `cl_waiting`, from `SHOW POOLS`. Reported here because it is exactly the convention's "current pending requests for an open connection" against the server pool, and again as `pgbouncer.client.connection.count{state=waiting}` because it is also a client-side state. The same number under two names is deliberate: the first is the semconv-native view of pool saturation, the second completes the client-side state breakdown.
//
// Instrument: updowncounter. Unit: {request}. Stability: development.
func (mb *MetricsBuilder) RecordDBClientConnectionPendingRequests(ts pcommon.Timestamp, value int64, attrs DBClientConnectionPendingRequestsAttributes) {
	mb.metricDBClientConnectionPendingRequests.record(mb.startTime, ts, value, attrs)
}

// RecordPgbouncerClientConnectionCount records one datapoint of pgbouncer.client.connection.count.
//
// Client connections held by PgBouncer, by state.
//
// The application-facing half of the pooler, which upstream `db.client.connection.*` does not model -- that convention describes a pool a client holds *to* a database, which here is the PostgreSQL side. Candidate semconv contribution once a second proxy provides evidence.
//
// Instrument: updowncounter. Unit: {connection}. Stability: development.
func (mb *MetricsBuilder) RecordPgbouncerClientConnectionCount(ts pcommon.Timestamp, value int64, attrs PgbouncerClientConnectionCountAttributes) {
	mb.metricPgbouncerClientConnectionCount.record(mb.startTime, ts, value, attrs)
}

// RecordPgbouncerClientConnectionDetailCount records one datapoint of pgbouncer.client.connection.detail.count.
//
// Client connections aggregated by database, role and connection state.
//
// From `SHOW CLIENTS`, at a finer grain than `SHOW POOLS`.
// The upstream exporter also dimensions this by `application_name`, which is set by the connecting client and is therefore unbounded by construction -- it is the label that turns a three-series metric into an N-series one. It is dropped here and the count aggregated over the remaining keys.
// The compat scope keeps `application_name`, because a user cutting over must see their existing series unchanged. That series cannot be reconstructed from this metric, which is why this entry is the one `compat_source: native` in the component.
//
// Instrument: updowncounter. Unit: {connection}. Stability: development.
func (mb *MetricsBuilder) RecordPgbouncerClientConnectionDetailCount(ts pcommon.Timestamp, value int64, attrs PgbouncerClientConnectionDetailCountAttributes) {
	mb.metricPgbouncerClientConnectionDetailCount.record(mb.startTime, ts, value, attrs)
}

// RecordPgbouncerClientConnectionMax records one datapoint of pgbouncer.client.connection.max.
//
