// Emit moves everything recorded since the last call into a pmetric.Metrics
// under resource, leaving the builder empty and ready for the next scrape.
func (mb *MetricsBuilder) Emit(resource pcommon.Resource) pmetric.Metrics {
	md := pmetric.NewMetrics()
	rm := md.ResourceMetrics().AppendEmpty()
	resource.CopyTo(rm.Resource())

	sm := rm.ScopeMetrics().AppendEmpty()
	sm.Scope().SetName(mb.scopeName)
	sm.Scope().SetVersion(mb.scopeVersion)
	ms := sm.Metrics()
	mb.metricDBClientConnectionCount.emit(ms)
	mb.metricDBClientConnectionIdleMin.emit(ms)
	mb.metricDBClientConnectionMax.emit(ms)
	mb.metricDBClientConnectionPendingRequests.emit(ms)
	mb.metricPgbouncerClientConnectionCount.emit(ms)
	mb.metricPgbouncerClientConnectionDetailCount.emit(ms)
	mb.metricPgbouncerClientConnectionMax.emit(ms)
	mb.metricPgbouncerClientCount.emit(ms)
	mb.metricPgbouncerClientWaitMax.emit(ms)
	mb.metricPgbouncerClientWaitTime.emit(ms)
	mb.metricPgbouncerDatabaseConnectionCount.emit(ms)
	mb.metricPgbouncerDatabaseConnectionMax.emit(ms)
	mb.metricPgbouncerDatabaseCount.emit(ms)
	mb.metricPgbouncerDatabaseDisabled.emit(ms)
	mb.metricPgbouncerDatabasePaused.emit(ms)
	mb.metricPgbouncerDatabaseReservePoolSize.emit(ms)
	mb.metricPgbouncerDNSCacheCount.emit(ms)
	mb.metricPgbouncerDNSQueryCount.emit(ms)
	mb.metricPgbouncerNetworkIO.emit(ms)
	mb.metricPgbouncerPoolCount.emit(ms)
	mb.metricPgbouncerPreparedStatementCount.emit(ms)
	mb.metricPgbouncerQueryCount.emit(ms)
	mb.metricPgbouncerQueryTime.emit(ms)
	mb.metricPgbouncerServerAssignmentCount.emit(ms)
	mb.metricPgbouncerServerCount.emit(ms)
	mb.metricPgbouncerTransactionCount.emit(ms)
	mb.metricPgbouncerTransactionTime.emit(ms)
	mb.metricPgbouncerUserConnectionMax.emit(ms)
	mb.metricPgbouncerUserCount.emit(ms)

	// A scrape that recorded nothing produces no scope and no resource, rather
	// than an empty envelope downstream has to filter out.
	if ms.Len() == 0 {
		return pmetric.NewMetrics()
	}
	return md
}
